Cho biết dòng kết quả thứ 2 khi chạy chương trình sau:
```cpp
#include <iostream>
using namespace std;
template <typename T>
T maxval(T x, T y) {
  static int count = 0;
  cout << ++count << ", ";
  return (x > y) ? x : y;
}
int main() {
  int i = maxval(3, 7);
  cout << i << endl;
  double d = maxval(6.34, 18.523);
  cout << d << endl;
  d = maxval(16.34, 28.523);
  cout << d << endl;
  char ch = maxval('a', '6');
  cout << ch << endl;
  d = maxval(5.2, 4.5);
  cout << d << endl;
  return 0;
}
```

